// Auto-generated Real Photo Asset Library from user-uploaded "Car Photos" folder
export const CAR_ASSETS = {
    "Toyota Fortuner": "data:image/avif;base64,",
    "Toyota Innova Crysta": "data:image/avif;base64,",
    "Toyota Corolla": "data:image/jpeg;base64,",
    "Honda City": "data:image/avif;base64,",
    "Honda Amaze": "data:image/avif;base64,",
    "Kia Seltos": "data:image/avif;base64,",
    "Mahindra XUV700": "data:image/jpeg;base64,",
    "Hyundai Creta": "data:image/avif;base64,",
    "Tata Nexon": "data:image/avif;base64,",
    "Maruti Swift": "data:image/avif;base64,"
};

export function getCarImage(brand, model) {
    const cleanBrand = (brand || '').trim();
    const cleanModel = (model || '').trim();
    const key = `${cleanBrand} ${cleanModel}`.trim();

    if (CAR_ASSETS[key]) return CAR_ASSETS[key];

    // Fuzzy matching by model or brand
    const searchStr = `${cleanBrand} ${cleanModel}`.toLowerCase();
    for (const [name, dataUri] of Object.entries(CAR_ASSETS)) {
        const nameLower = name.toLowerCase();
        if (cleanModel && nameLower.includes(cleanModel.toLowerCase())) return dataUri;
        if (searchStr && (nameLower.includes(searchStr) || searchStr.includes(nameLower))) return dataUri;
    }

    return CAR_ASSETS['Toyota Fortuner'] || '';
}
